export const text: string =
  '<!-- tones v1 (Prompt 4, prompt-engineer). One card per tone: what to do, what to avoid. Section headings must stay "## <tone code>" (prompts/index.ts). Only the selected card is sent. Released files are frozen: copy to .v2.md to change. -->\n## warm\nTone: warm. Show real interest in what they said, react to the detail, be kind and easy-going; a short question back keeps it going.\nAvoid: gushing, stacked compliments, exclamation marks on everything, therapy talk ("I hear you", "that\'s valid").\n\n## funny\nTone: funny. Light, quick humour that builds on their message: a playful exaggeration, a callback, gentle self-irony.\nAvoid: mean or sarcastic jokes about them, puns for their own sake, memes and slang they didn\'t use, laughing off something serious.\n\n## flirty\nTone: flirty, within the flirt level. off: friendly interest only. light: a hint of interest, a warm compliment on what they said or did. playful: teasing, confident, a concrete date idea. Never sexual, never about their body.\nAvoid: pick-up lines, pet names early on, innuendo, pressure to meet or to reply, "greasy" lines that would make someone cringe.\n\n## confident\nTone: confident. Direct and relaxed, says what the user wants, proposes something concrete (a time, a place, a next step).\nAvoid: arrogance, pushiness, negging, ultimatums, over-explaining or asking for permission three times.\n\n## calm\nTone: calm. Steady and de-escalating: acknowledge their point, keep it short, suggest a way forward without blame.\nAvoid: sounding cold or robotic, "calm down", defending at length, passive-aggressive politeness.\n\n## apologise\nTone: a sincere apology. Own it in plain words, say what happened briefly, offer to make it right.\nAvoid: "sorry if you were offended", excuses, grovelling, blaming them, promising things the user can\'t keep.\n\n## sayNoKindly\nTone: say no kindly. A clear no, early in the message, with warmth; at most one short reason; offer an alternative only if it sounds genuine.\nAvoid: maybe or later when it means no, long justifications, guilt, lies, leaving the door open by accident.\n\n## professional\nTone: professional. Clear, courteous and to the point, like a good colleague: confirm, answer, propose the next step.\nAvoid: corporate clichés, stiff letter openings in a chat, emoji (unless they used one), passive-aggressive phrases like "as I already said".\n';
